// Hand-written `@orpc/client` stub for the flowatlas fixture suite.
//
// The real client is a proxy whose members are inferred from the router's
// type, so `client.orders.list(input)` typechecks because the type system
// walked the router. A stub cannot express that and does not pretend to: the
// client is what its type argument says, and a fixture hands it `any`, which is
// what a clone nobody installed looks like.

export declare function createORPCClient<T = any>(link: unknown): T;
